def verify_no_overflow(trace):
    volume = 0
    for evt in trace:
        if evt in ['HOT_WATER', 'COLD_WATER']:
            volume += 1
        elif evt == 'DRAIN_VALVE':
            volume -= 2
        assert volume <= 6, f'Safety violation: tank volume exceeded 6 at {evt}'
    print('Safety verification passed: No overflow events detected.')
